pub struct ReachCase {
    pub id: &'static str,
    pub length: f64, pub od: f64, pub wall: f64, pub e: f64, pub g: f64,
    /// The one free DOF at N1 (None: all six free).
    pub free: Option<usize>,
    pub spring: Option<f64>,
    /// (local DOF at N1, load).
    pub loads: &'static [(usize, f64)],
    /// The section as the product derives it (A, I, J).
    pub area: f64, pub i: f64, pub j: f64,
    /// (local DOF at N1, exact reference rounded once).
    pub exact: &'static [(usize, f64)],
    pub b: i32, pub e_min: i32, pub e_max: i32,
}

